import json, base64, sys, glob, os
IDS=["1844748127814183717","1843547312959065138","1844735562296076053","1832208184829815962","1844623441920000059","1842277743427687737","1844354293432320031","1843552279434086285","1844294398771200045","1844276782694400053","1843473831194478743","1843988506059556678","1842283406259093714","1843978997950200606","1843708575498669206"]
def dec(d):
    d=d+'='*(-len(d)%4); return base64.urlsafe_b64decode(d).decode('utf-8','replace')
def walk(p,plain,html,files):
    if p.get('filename'): files.append(p['filename'])
    mt=p.get('mimeType',''); d=(p.get('body') or {}).get('data')
    if d and not p.get('filename'):
        if mt.startswith('text/html'): html.append(dec(d))
        else: plain.append(dec(d))
    for c in p.get('parts') or []: walk(c,plain,html,files)
def process(t,n):
    out=[]
    for m in t.get('messages',[]):
        h={x['name'].lower():x['value'] for x in m['payload'].get('headers',[])}
        for k in ['From','To','Cc','Date','Subject']: out.append(f"{k}: {h.get(k.lower(),'')}")
        plain,html,files=[],[],[]; walk(m['payload'],plain,html,files)
        out.append("Attachments: "+", ".join(files))
        out.append("\n".join(plain) if plain else "\n".join(html))
        out.append("\n"+"="*60+"\n")
    open(f"/tmp/emails/A_{n}.txt","a").write("\n".join(out))
    m=t['messages'][0]; h={x['name'].lower():x['value'] for x in m['payload']['headers']}
    print(f"A_{n}.txt | From: {h.get('from')} | Subject: {h.get('subject')}")
def load(s):
    j=json.loads(s) if isinstance(s,str) else s
    if isinstance(j,dict) and 'result' in j and isinstance(j['result'],str): j=json.loads(j['result'])
    return j
